def W(a, b, *peaks): return {"from": a, "to": b, "peak": [list(p) for p in peaks]}
def H_(id, name, latin, group, windows, time, patterns, waters, src, conf, note, temp=None, applies=None):
    return dict(id=id, name=name, latin=latin, group=group, windows=windows, time=time, patterns=patterns,
                waters=waters, sources=src, confidence=conf, note=note, water_temp_f=temp, applicability=applies)
