 H_("lbc","Little Black Caddis (Black Caddis)","Chimarra aterrima","caddis",[W("04-20","06-30",("05-01","05-14"))],"Noon to 10 pm",
    [["Black caddis dry / Elk Hair Caddis (black)",[16,18,20]],["Black caddis pupa / soft hackle",[16,18]]],[P,C,H,SM],["t2t","otf","mca","birdtrout","morningsun"],R,"Michigan charts: Apr 20-Jun 30 (peak May 1-14). Birdtrout lists Little Black Caddis and Grannom for southern lower MI (Apr-May)."),
 H_("gran","Grannom (Mother's Day Caddis)","Brachycentrus americanus","caddis",[W("04-20","07-31",("04-20","05-31"))],"2 pm to dark",
    [["Grannom / Elk Hair Caddis",[12,14,16]],["Caddis emerger / pupa",[14,16]]],[H,C,SM],["t2t","otf","birdtrout"],R,"Birdtrout (southern MI): Apr-May; northern charts run to Jul 31 (shown as tail). Peak window Apr 20-May 31 is our reading of the Birdtrout/regional data."),
