 H_("hebe","Hebe / Little Yellow Quill","Heptagenia / Stenacron","mayfly",[W("06-15","09-30",("07-01","07-31"))],"Noon to evening",
    [["Little Yellow Quill / pale yellow dry",[16,18]]],[SM,C],["t2t"],R,"Single northern chart source; nominal."),
 H_("ants","Ants & Beetles (terrestrials)","Formicidae / Coleoptera","terrestrial",[W("06-01","10-15",("07-01","09-30"))],"Daytime and evening",
    [["Black / cinnamon flying ant",[12,14,16,18,20,22,24]],["Foam beetle / Crowe beetle",[12,14,16]]],[P,C,H,SM,BG],["t2t","mca"],R,"Trails To Trout: ants Jun 15-Sep 30 (#12-24), beetles Jun 1-Sep 30; Motor City Anglers: ants Jul-Sep #12-18. Peak Jul-Sep is our simplification. Good when Paint Creek warms and bugs are scarce."),
 H_("hoppers","Hoppers & Crickets (terrestrials)","Melanoplus / Gryllidae","terrestrial",[W("07-01","10-15",("07-15","09-30"))],"Midday",
    [["Dave's Hopper (hopper/dropper)",[8,10]],["Cricket pattern",[10,12,14]]],[P,C,H,SM],["hub_paint","hub_hatch","t2t","mca"],L,"Hub lists Hopper/Dropper on Paint Creek (Jul-Aug, Dave's Hopper #8-10, midday, ideal ~72F water - but see Paint Creek's ~70F stress limit). Trails To Trout: hoppers Jul 15-Sep 30, crickets Jul 1-Oct 15.",[65,80]),
 H_("trico","Trico","Tricorythodes spp.","mayfly",[W("07-15","10-20",("07-20","09-15"))],"Early morning - dawn to mid-morning (spinner falls)",
    [["Trico Spinner",[22,24,26]],["Trico dun / cluster",[22,24]]],[SM,C,H],["hub_hatch","t2t","mca"],R,"Hub: Jul-Sep (listed for northern rivers, not Paint/Clinton); Trails To Trout Jul 20-Oct 20 (#22-26). Needs 6X tippet.",[62,75]),
