doc = dict(generated=datetime.date.today().isoformat(),
  note="Half-month windows. 'confidence': local = a source lists this hatch for that water; regional = Michigan/southern-lower-MI chart, not water-specific; rule = our rule of thumb. SE Michigan typically runs ~1-2 weeks earlier than northern-MI dates (Trails To Trout, Norrik). Always verify locally.",
  waters=[{"id":"all","label":"All"},{"id":"paint","label":"Paint Creek"},{"id":"clinton","label":"Clinton River"},{"id":"huron","label":"Huron River"},{"id":"small","label":"Other small streams"},{"id":"big","label":"Big water / steelhead"}],
  sources={k:{"label":v[0],"url":v[1]} for k,v in S.items()}, hatches=hatches)
json.dump(doc, open("hatch-calendar.json","w"), indent=1, ensure_ascii=False)
print(len(hatches),"hatches")
